import sys

def can_reach_island(n, k, l, d):
    p = [i for i in range(k)] + [i for i in range(k-1, -1, -1)]
    max_tide_effect = max(p)

    for i in range(n):
        if d[i] > l:
            return False

    dp = [[False] * (n + 1) for _ in range(2 * k)]
    dp[0][0] = True

    for t in range(2 * k):
        for x in range(n + 1):
            if dp[t % (2 * k)][x]:
                if x < n and d[x] + p[t % (2 * k)] <= l:
                    dp[(t + 1) % (2 * k)][x + 1] = True
                dp[(t + 1) % (2 * k)][x] = True

    for t in range(2 * k):
        if dp[t][n]:
            return True

    return False

input = sys.stdin.read().split()
index = 0
t = int(input[index])
index += 1
results = []

for _ in range(t):
    n = int(input[index])
    k = int(input[index + 1])
    l = int(input[index + 2])
    index += 3
    d = list(map(int, input[index:index + n]))
    index += n
    results.append("Yes" if can_reach_island(n, k, l, d) else "No")

print("\n".join(results))
